function normalizeRouteAuthz(route, id, path, isPage, auth, context) {
    if ('access' in route) {
        throw new Error(`Client route "${id}" uses removed access; declare authz instead.`);
    }
    const value = 'authz' in route ? route.authz : undefined;
    if (value !== undefined) {
        if (!isPage)
            throw new Error(`Client route group "${id}" cannot declare authz.`);
        if (value === 'skip' || value === 'unrestricted')
            return value;
        if (!value ||
            typeof value !== 'object' ||
            !('resource' in value) ||
            !value.resource ||
            typeof value.resource !== 'object' ||
            typeof value.resource.type !== 'string' ||
            !value.resource.type.trim() ||
            typeof value.resource.id !== 'string' ||
            !value.resource.id.trim() ||
            typeof value.action !== 'string' ||
            !value.action.trim())
            throw new Error(`Client route "${id}" must use authz "skip", "unrestricted" or { resource: { type, id }, action }.`);
        return Object.freeze({
            resource: Object.freeze({ ...value.resource }),
            action: value.action,
        });
    }
    if (!isPage)
        return 'skip';
    if (context.ancestorAuthz !== undefined)
        return context.ancestorAuthz;
    // An omission never stops the application: a protected page stays closed to all but unrestricted identities.
    const fallback = context.surface === 'dev' ||
        (context.surface === 'app' && auth !== 'required')
        ? 'skip'
        : 'unrestricted';
    if (isDevelopment())
        console.warn(`Client route "${id}" at "${path}" does not declare authz; using "${fallback}". Declare authz on this page: { resource: { type, id }, action } or "skip".`);
    return fallback;
}

/**
 * The current locale, the ones available, and a way to change it.
 *
 * The switch is atomic: every namespace's resources for the new locale load before i18next changes language, so no
 * frame is ever rendered half-translated.
 */
export function useLocale() {
    // Optional so a language control can be dropped into any tree, including one composed without i18n; with no runtime
    // it reports no languages, which is what makes such a control render nothing rather than fail.
    const runtime = useOptionalI18nRuntime();
    const [locale, setCurrentLocale] = useState(() => runtime?.getLocale() ?? '');
    const [switching, setSwitching] = useState(false);
    const [error, setError] = useState();
    useEffect(() => {
        if (!runtime)
            return;
        const handleChange = (next) => setCurrentLocale(next);
        runtime.i18n.on('languageChanged', handleChange);
        // A language may have changed between the initial render and this subscription.
        setCurrentLocale(runtime.getLocale());
        return () => {
            runtime.i18n.off('languageChanged', handleChange);
        };
    }, [runtime]);
    const setLocale = useCallback(async (next) => {
        if (!runtime || next === runtime.getLocale())
            return;
        setSwitching(true);
        setError(undefined);
        try {
            await runtime.changeLanguage(next);
        }
        catch (cause) {
            setError(cause instanceof Error ? cause : new Error(String(cause)));
            throw cause;
        }
        finally {
            setSwitching(false);
        }
    }, [runtime]);

