/** The booking whose `[startAt, endAt)` overlaps the candidate slot. */
async function findOverlap(
  connection: DatabaseConnection,
  roomId: string,
  startAt: string,
  endAt: string,
): Promise<RoomBookingRow | undefined> {
  const found = await connection
    .repository<RoomBookingRow>('roomBookings')
    .findMany({
      filter: (filter) =>
        filter.and([
          filter.string('roomId').eq(roomId),
          filter.string('status').ne('cancelled'),
          filter.date('startAt').before(endAt),
          filter.date('endAt').after(startAt),
        ]),
      sort: (sort) => sort.field('startAt').asc(),
      limit: 1,
    });
  return found[0];
}

